class CrestApiFsEmptyRootTest : public ::testing::Test {
 protected:
  std::string m_root;

  void SetUp() override {
    m_root =
        "/tmp/crest_fs_empty_root_test_" +
        std::to_string(
            ::testing::UnitTest::GetInstance()->current_test_info()->line());
    std::filesystem::remove_all(m_root);
    std::filesystem::create_directories(m_root);
  }

  void TearDown() override { std::filesystem::remove_all(m_root); }
}

void SetUp() override {
    m_root =
        "/tmp/crest_fs_empty_root_test_" +
        std::to_string(
            ::testing::UnitTest::GetInstance()->current_test_info()->line());
    std::filesystem::remove_all(m_root);
    std::filesystem::create_directories(m_root);
  }

TEST_F(CrestApiFsEmptyRootTest, ListTagsIsEmpty) {
  CrestApiFs api(true, m_root);
  TagSetDto tags;
  ASSERT_NO_THROW(tags = api.listTags("", 1000, 0, "name:ASC"));
  EXPECT_EQ(tags.size(), 0u);
}

TEST_F(CrestApiFsEmptyRootTest, ListGlobalTagsIsEmpty) {
  CrestApiFs api(true, m_root);
  GlobalTagSetDto globalTags;
  ASSERT_NO_THROW(globalTags = api.listGlobalTags("", 1000, 0, "name:ASC"));
  EXPECT_EQ(globalTags.size(), 0u);
}
